package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
import org.springframework.core.env.*;
final class CustomerRepliesBrowserAcceptance {
 static void run(BrowserTest h)throws Exception{
  String id;try(var db=h.store.open()){db.update("DELETE FROM os_outbox");PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","ReplyBrowserCustomer","role","requester","password",WorkflowSupport.PASSWORD));Service.createAccount(db,map("name","ReplyBrowserAgent","role","agent","password",WorkflowSupport.PASSWORD));String user=RecordAccess.owner(db,"ReplyBrowserCustomer"),group=Service.create(db,"sys_user_group",map("short_description","Reply support team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member VALUES(?,?)",group,RecordAccess.owner(db,"ReplyBrowserAgent"));db.update("UPDATE os_user SET email='browser@example.invalid',email_verified=1 WHERE user_id=?",user);String account=CustomerAccounts.save(db,"",map("name","Reply browser account","group_id",group,"active",true,"revision",0)).get("account_id").toString();CustomerAccounts.manage(db,account,map("operation","contact","username","ReplyBrowserCustomer","active",true,"revision",0));String entitlement=objects(CustomerAccounts.manage(db,account,CustomerCasesAcceptance.entitlement("",0,0)).get("entitlements")).getFirst().get("entitlement_id").toString();db.viewerId=user;db.viewerRole="requester";id=CustomerCases.create(db,entitlement,map("account_revision",1,"contact_revision",1,"entitlement_revision",1,"summary","A customer needs a reply","description","Please explain the workaround","key",Values.id())).get("sys_id").toString();PlatformFoundationTest.bind(db);Service.audit(db,Service.record(db,"customer_case",id),"admin","note",map("body","Internal staff diagnosis"));db.connection.commit();}
  var properties=((ConfigurableEnvironment)h.environment).getPropertySources();try(var sink=new MailSink();var p=Playwright.create();var browser=p.chromium().launch();var customerContext=browser.newContext();var staffContext=browser.newContext();var adminContext=browser.newContext()){
   properties.addFirst(new MapPropertySource("customer-reply-browser",ReleaseAcceptance.settings(sink)));
   var customer=customerContext.newPage();customer.navigate(h.base()+"/login");customer.getByLabel("Username").fill("ReplyBrowserCustomer");customer.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);customer.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enter your workspace")).press("Enter");customer.waitForURL("**/requests");customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer service").setExact(true)).press("Enter");customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer email preferences")).press("Enter");assertThat(customer.locator("main")).containsText("verified email address");customer.getByLabel("Email published customer replies").selectOption("true");CustomerCasesBrowserAcceptance.click(customer,"Save customer email preference");ReleaseBrowserAcceptance.accessible(customer);customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-reply-preferences-light.png")).setFullPage(true));
   var staff=staffContext.newPage();h.login(staff,"ReplyBrowserAgent");staff.navigate(h.base()+"/record/customer_case/"+id);staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer replies").setExact(true)).press("Enter");staff.getByLabel("Public reply").fill("Try the reviewed workaround <script>alert(1)</script>\nThen let us know through the case comments.");staff.getByLabel("Reply delivery").selectOption("true");ReleaseBrowserAcceptance.accessible(staff);staff.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-reply-compose-light.png")).setFullPage(true));CustomerCasesBrowserAcceptance.click(staff,"Publish customer reply");assertThat(staff.locator("main")).containsText("Email queued");assertThat(staff.locator("main script")).hasCount(0);assertFalse(staff.locator("main").innerText().contains("Internal staff diagnosis"));
   customer.navigate(h.base()+"/record/customer_case/"+id+"/replies");assertThat(customer.locator("main")).containsText("Try the reviewed workaround <script>");assertThat(customer.getByLabel("Public reply")).hasCount(0);assertEquals("pre-wrap",customer.locator(".customer-reply-body").evaluate("el=>getComputedStyle(el).whiteSpace"));assertFalse(customer.locator("main").innerText().contains("Internal staff diagnosis"));assertTrue(new DeliveryWorker(h.store,new SmtpDelivery(h.environment)).runOne(System.currentTimeMillis()+100));String mail=sink.receive();assertTrue(mail.contains("Try the reviewed workaround"));assertFalse(mail.contains("Internal staff diagnosis"));customer.reload();assertThat(customer.locator("main")).containsText("Accepted by mail server");CustomerCasesBrowserAcceptance.click(customer,"Dark mode");customer.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(customer);assertTrue((Boolean)customer.evaluate("document.documentElement.scrollWidth<=innerWidth"));customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-reply-read-dark.png")).setFullPage(true));
   var admin=adminContext.newPage();h.login(admin,"admin");admin.navigate(h.base()+"/admin/delivery");admin.getByLabel("Message kind").selectOption("customer_reply");CustomerCasesBrowserAcceptance.click(admin,"Filter deliveries");assertThat(admin.locator("main")).containsText("email.customer_reply");assertFalse(admin.locator("main").innerText().contains("browser@example.invalid"));
   customer.navigate(h.base()+"/customer-service/notifications");customer.getByLabel("Email published customer replies").selectOption("false");CustomerCasesBrowserAcceptance.click(customer,"Save customer email preference");staff.reload();assertThat(staff.locator("main")).containsText("Email is unavailable");staff.getByLabel("Public reply").fill("A portal-only follow-up");CustomerCasesBrowserAcceptance.click(staff,"Publish customer reply");customer.navigate(h.base()+"/record/customer_case/"+id+"/replies");assertThat(customer.locator("main")).containsText("Available in customer portal");
  }finally{properties.remove("customer-reply-browser");}
 }
}
